import { loadFixture } from "@nomicfoundation/hardhat-toolbox-viem/network-helpers";
import hre from "hardhat";
import { getCrayOrder, getCraySignOnOrder, MAX_ALLOWANCE_VALUE, signPaymentData } from "./_utils_";

describe("OneInch Integration", function () {
  async function deploy() {

    const provider = await hre.viem.getPublicClient()
    const publicClient = await hre.viem.getPublicClient()
    const [owner, otherAccount] = await hre.viem.getWalletClients()
// const craySigner = owner
    // set time

    // Contracts are deployed using the first signer/account by default
    const usdc = await hre.viem.deployContract("MockERC20", ["USDC", "USDC", 6])
    const usde = await hre.viem.deployContract("MockERC20", ["USDE", "USDE", 18])
    await usdc.write.mint([owner.account.address, 100*10**6])
    await usde.write.mint([owner.account.address, 100*10**18])
    const orderVerifier = await hre.viem.deployContract("CrayOrderVerifier")
    const crayHorizon = await hre.viem.deployContract("FusionDestination", [orderVerifier.address, owner.account.address, owner.account.address])
    const oneInch = await hre.viem.deployContract("Mock1Inch", [usde.address, 200000, owner.account.address])
    // solver approve
    await usdc.write.approve([crayHorizon.address, MAX_ALLOWANCE_VALUE])
    await usde.write.approve([crayHorizon.address, MAX_ALLOWANCE_VALUE])
    // transfer some USDC to other account
    await usdc.write.transfer([otherAccount.account.address, 50*10**6])
    // user approve
    await otherAccount.writeContract({
      address: usdc.address,
      functionName: "approve",
      abi: usdc.abi,
      args: [orderVerifier.address, MAX_ALLOWANCE_VALUE],
    })
    // await usdc.connect(otherAccount).write.approve([orderVerifier.address, MAX_ALLOWANCE_VALUE])

    const decimals = await usdc.read.decimals()
    return {
      usdc,
      usde,
      owner,
      otherAccount,
      publicClient,
      decimals,
      orderVerifier,
      provider,
      crayHorizon,
      oneInch,
      craySigner: owner
    }
  }

  it("should create and fulfill with swap order successfully", async function () {
    const toAddress = "0xd8da6bf26964af9d7eed9e03e53415d37aa96045"
    const { usdc, owner, orderVerifier, provider, crayHorizon, craySigner, oneInch, usde, otherAccount } = await loadFixture(deploy)
    const amount = 15 * 10 ** 6

    console.log("sender usdc bal", await usdc.read.balanceOf([otherAccount.account.address]))
    console.log("receiver usdc bal", await usdc.read.balanceOf([toAddress]))
    console.log("sender usde bal", await usde.read.balanceOf([otherAccount.account.address]))
    console.log("receiver usde bal", await usde.read.balanceOf([toAddress]))
    const blockNumber = await provider.getBlock()
    const time = blockNumber.timestamp
    const { typedOrder, orderHash } = getCrayOrder({
      chainId: provider.chain.id,
      tokenAddress: usdc.address,
      toToken: usde.address,
      owner: otherAccount,
      orderVerifier,
      toAddress,
      amount,
    }) as any
    const { signedOrder } = await signPaymentData(otherAccount, typedOrder)
    const res = await Promise.all(
      typedOrder.message.inputs
        .filter((_: any) => _.chainId === provider.chain.id)
        .map((input: any, index: number) => {
          const payload = {
            order: typedOrder.message,
            solverOutputAmount: typedOrder.message.output.minAmountOut,
            index,
            userSignature: signedOrder,
          }
          return crayHorizon.write.createOrder([payload])
        })
    )
    console.log('filler', owner.account.address)
    const sign = await getCraySignOnOrder(craySigner, owner.account.address, orderHash)
    // const oneInchCalldata = ""
    const swapParams = {
      makerAsset: usdc.address,
      swapContract: oneInch.address,
      swapData: '0x'
    }
    console.log(swapParams)
    let fulfill = await crayHorizon.write.fullFillOrder([{ order: typedOrder.message, fullfiller: owner.account.address, outputAmount: typedOrder.message.output.minAmountOut }, sign, swapParams])
    console.log({ fulfill })
    const balance = await usde.read.balanceOf([toAddress])
    console.log('receiver usde bal after', balance)
    if (balance !== BigInt(amount)) {
      throw new Error("Receiver did not get expected funds")
    }
  })
})
  ; (BigInt.prototype as any).toJSON = function () {
    return this.toString()
  } /** patch big int https://github.com/GoogleChromeLabs/jsbi/issues/30#issuecomment-953187833 */
